"use client";

import Image from "next/image";
import { useEffect, useMemo, useState } from "react";
import { AnimatePresence, motion, useReducedMotion, useScroll, useSpring } from "framer-motion";
import { ArrowDownRight, ArrowUpRight, ChevronRight, Menu, X } from "lucide-react";
import { MinimalistHero } from "@/components/ui/minimalist-hero";
import { chapters } from "@/data/archive";
import archiveData from "@/public/data/klr-archive.json";

const nav = ["Home", "Journey", "Stats", "Centuries", "Records", "Analytics", "Predict", "Ask KLR"];
type FormatName = keyof typeof archiveData.formats;

function Navigation() {
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState("home");
  useEffect(() => {
    const sections = nav.map(n => document.getElementById(n.toLowerCase().replace(" ", "-"))).filter(Boolean) as HTMLElement[];
    const observer = new IntersectionObserver(e => e.forEach(x => x.isIntersecting && setActive(x.target.id)), { rootMargin: "-45% 0px -45%" });
    sections.forEach(s => observer.observe(s)); return () => observer.disconnect();
  }, []);
  return <>
    <header className="nav-shell"><a className="wordmark" href="#home">KLR<span>01</span></a><nav className="desktop-nav" aria-label="Primary navigation">{nav.map(n => <a className={active === n.toLowerCase().replace(" ", "-") ? "active" : ""} href={`#${n.toLowerCase().replace(" ", "-")}`} key={n}>{n}</a>)}</nav><button className="menu-button" onClick={() => setOpen(v => !v)} aria-label={open ? "Close menu" : "Open menu"}>{open ? <X /> : <Menu />}</button></header>
    <AnimatePresence>{open && <motion.nav className="mobile-nav" initial={{ opacity: 0, clipPath: "inset(0 0 100% 0)" }} animate={{ opacity: 1, clipPath: "inset(0)" }} exit={{ opacity: 0, clipPath: "inset(0 0 100% 0)" }} aria-label="Mobile navigation">{nav.map((n,i) => <motion.a initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i*.04 }} onClick={() => setOpen(false)} href={`#${n.toLowerCase().replace(" ", "-")}`} key={n}><span>0{i+1}</span>{n}</motion.a>)}</motion.nav>}</AnimatePresence>
  </>;
}

function Journey() {
  return <section id="journey" className="journey"><div className="section-intro"><p>01 / The journey</p><h2>A CAREER<br /><i>IN MOTION</i></h2><span>Scroll through the roles, resets and reinventions that shaped a modern Indian batter.</span></div>
    <div className="chapter-list">{chapters.map((c, i) => <article className="chapter" key={c.year}><div className="chapter-year">{c.year}</div><motion.div className="chapter-image" initial={{ opacity: .25, scale: .94 }} whileInView={{ opacity: 1, scale: 1 }} viewport={{ amount: .45 }} transition={{ duration: .8 }}><Image src={c.image} alt={`KL Rahul — ${c.kicker}`} fill sizes="(max-width: 768px) 90vw, 45vw" /></motion.div><div className="chapter-copy"><p>{c.kicker}</p><h3>{c.title}</h3><span>{c.body}</span><b>{c.stat}</b></div><div className="chapter-index">0{i+1}</div></article>)}</div>
  </section>;
}

function StatsLab() {
  const [format, setFormat] = useState<FormatName>("Test");
  const stats = archiveData.formats[format];
  const years = useMemo(() => archiveData.yearly.filter(row => row.format === format).sort((a,b) => a.year-b.year), [format]);
  const points = useMemo(() => { const peak=Math.max(...years.map(y=>y.runs),1); return years.map((v,i,a)=>`${a.length===1?50:(i/(a.length-1))*100},${92-(v.runs/peak)*82}`).join(" ") }, [years]);
  const statStrip = [{label:"Runs",value:stats.runs.toLocaleString("en-IN")},{label:"Average",value:stats.average?.toFixed(2)??"—"},{label:"Strike rate",value:stats.strikeRate?.toFixed(2)??"—"},{label:"100s / 50s",value:`${stats.hundreds} / ${stats.fifties}`}];
  return <section id="stats" className="stats-section"><div className="stats-head"><p>02 / Career numbers</p><h2>NUMBERS<br />DON’T <i>LIE.</i></h2></div><div className="data-stamp">CRICSHEET · {archiveData.coverage.innings} REGULATION INNINGS · UPDATED {archiveData.lastUpdated}</div><div className="stat-strip">{statStrip.map(s => <div key={s.label}><strong>{s.value}</strong><span>{s.label} · {format}</span></div>)}</div><div id="analytics" className="lab"><div className="lab-title"><span>Verified year-by-year runs</span><h3>THE PULSE</h3><p>{stats.innings} innings across {stats.matches} matches. Select a format to redraw the historical series directly from processed Cricsheet deliveries.</p></div><div className="format-tabs" role="tablist" aria-label="Format">{(Object.keys(archiveData.formats) as FormatName[]).map(f => <button role="tab" aria-selected={format===f} onClick={() => setFormat(f)} key={f}>{f}</button>)}</div><div className="chart-wrap"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-label={`${format} verified annual runs`}><defs><linearGradient id="gold" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#c9a96e" stopOpacity=".5"/><stop offset="1" stopColor="#c9a96e" stopOpacity="0"/></linearGradient></defs><polygon points={`0,100 ${points} 100,100`} fill="url(#gold)"/><polyline points={points} fill="none" stroke="#d8bd89" strokeWidth="1.2" vectorEffect="non-scaling-stroke"/></svg><div className="chart-labels"><span>{years[0]?.year}</span><b>{format.toUpperCase()} · HIGH {stats.highest}</b><span>{years.at(-1)?.year}</span></div></div></div></section>;
}

const centuryImages: Record<string,string> = { Test:"/images/rahul/journey/test-batter.jpg", ODI:"/images/rahul/gallery/world-cup.webp", T20I:"/images/rahul/journey/india-batting.jpg", IPL:"/images/rahul/gallery/ipl-batting.webp" };
function CenturyVault() { const [filter,setFilter]=useState<"ALL"|FormatName>("ALL"); const filtered=archiveData.centuries.filter(c=>filter==="ALL"||c.format===filter); const [selected,setSelected]=useState(0); useEffect(()=>setSelected(0),[filter]); const c=filtered[Math.min(selected,filtered.length-1)]; return <section id="centuries" className="vault"><div className="vault-title"><p>03 / {archiveData.centuries.length} dataset centuries</p><h2>CENTURY<br /><i>VAULT</i></h2></div><div className="format-tabs vault-tabs" role="tablist" aria-label="Century format">{["ALL",...Object.keys(archiveData.formats)].map(f=><button role="tab" aria-selected={filter===f} onClick={()=>setFilter(f as "ALL"|FormatName)} key={f}>{f}</button>)}</div>{c&&<><div className="vault-stage"><AnimatePresence mode="wait"><motion.div key={c.match_id} className="vault-image" initial={{ opacity:0, scale:1.06 }} animate={{ opacity:1, scale:1 }} exit={{ opacity:0 }}><Image src={centuryImages[c.format]} alt={`KL Rahul ${c.runs} against ${c.opponent}`} fill sizes="65vw"/></motion.div></AnimatePresence><div className="vault-score"><span>{c.format} · {c.date}</span><strong>{c.runs}</strong><p>VS {c.opponent} · {c.venue}</p><div className="innings-context"><span>{c.balls} BALLS</span><span>SR {c.strike_rate}</span><span>{c.fours}×4 · {c.sixes}×6</span><span>IMPACT {c.impact_score}</span></div></div></div><div className="vault-list">{filtered.map((item,i)=><button className={selected===i?"selected":""} onClick={()=>setSelected(i)} key={`${item.match_id}-${item.innings_number}`}><span>{String(i+1).padStart(2,"0")}</span><b>{item.runs}</b><em>vs {item.opponent} · {item.venue}</em><ChevronRight/></button>)}</div></>}<p className="data-note">Scores and match context are derived delivery-by-delivery from the supplied Cricsheet archives. Super overs are excluded.</p></section> }

function Records() { const formats=Object.entries(archiveData.formats) as [FormatName,(typeof archiveData.formats)[FormatName]][]; return <section id="records" className="records"><div className="records-title"><p>04 / Supported records</p><h2>THE<br/><i>RECORDS</i></h2><span>Only dataset-derivable statistics are shown. No external ranking or unsupported record claims.</span></div><div className="record-wall">{formats.map(([format,s])=><article key={format}><span>{format}</span><strong>{s.runs.toLocaleString("en-IN")}</strong><p>RUNS · {s.innings} INNINGS</p><dl><div><dt>HIGH</dt><dd>{s.highest}</dd></div><div><dt>AVG</dt><dd>{s.average}</dd></div><div><dt>SR</dt><dd>{s.strikeRate}</dd></div><div><dt>100</dt><dd>{s.hundreds}</dd></div></dl></article>)}</div><div className="impact-list"><h3>TOP IMPACT INNINGS</h3>{archiveData.topImpact.slice(0,5).map((i,n)=><div key={`${i.date}-${i.runs}`}><span>0{n+1}</span><b>{i.runs}</b><em>vs {i.opponent}<small>{i.format} · {i.venue} · {i.date}</small></em><strong>{i.impact_score}</strong></div>)}</div><p className="formula-note">KLR10 proprietary metric · {archiveData.formulae.impactScore}</p></section> }

function Gallery() { const images=["/images/rahul/gallery/celebration.webp","/images/rahul/gallery/ipl-batting.webp","/images/rahul/hero/rahul-studio-portrait.jpg","/images/rahul/gallery/world-cup.webp","/images/rahul/gallery/resilience.jpg"]; return <section id="gallery" className="gallery"><div className="gallery-head"><p>04 / Photo story</p><h2>FRAME<br />BY <i>FRAME</i></h2></div><div className="filmstrip">{images.map((src,i)=><figure key={src} className={`frame frame-${i+1}`}><Image src={src} alt={`KL Rahul archive frame ${i+1}`} fill sizes="(max-width: 768px) 80vw, 30vw"/><figcaption><span>0{i+1}</span>{["Release","The IPL years","Stillness","India blue","Resilience"][i]}</figcaption></figure>)}</div></section> }

type Prediction = { predicted_runs:number; expected_range:number[]; probability_30_plus:number; probability_50_plus:number; probability_100_plus:number; disclaimer:string };
function Predictor() { const opponents=[...new Set(archiveData.opponents.map(o=>o.opponent))].sort(); const venues=[...new Set(archiveData.centuries.map(c=>c.venue))].sort(); const [format,setFormat]=useState<FormatName>("ODI"); const [opponent,setOpponent]=useState(opponents[0]); const [venue,setVenue]=useState(venues[0]); const [position,setPosition]=useState(4); const [prediction,setPrediction]=useState<Prediction|null>(null); const [status,setStatus]=useState("MODEL READY · RIDGE + CALIBRATED CLASSIFIERS"); async function run(){setStatus("CALCULATING FROM HISTORICAL FEATURES…");try{const res=await fetch(`${process.env.NEXT_PUBLIC_KLR_API_URL||"http://localhost:8000"}/predict`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({format,opponent,venue,batting_position:position,innings_number:1,chasing:false})});if(!res.ok)throw new Error();setPrediction(await res.json());setStatus("MACHINE-LEARNING ESTIMATE")}catch{setStatus("START THE FASTAPI SERVICE ON PORT 8000");setPrediction(null)}} return <section id="predict" className="predict"><div><p>06 / Model lab</p><h2>PREDICT<br />THE NEXT<br /><i>INNINGS</i></h2><div className="model-note"><b>TEST WINDOW</b><span>{archiveData.modelMetrics.split.test_start} → {archiveData.modelMetrics.split.test_end}</span><b>BEST MAE</b><span>{archiveData.modelMetrics.regression[archiveData.modelMetrics.selected_regressor as keyof typeof archiveData.modelMetrics.regression].mae} runs</span></div></div><div className="predict-panel"><span>{status}</span><h3>{prediction?prediction.predicted_runs:"—"}</h3><p>{prediction?`EXPECTED RANGE ${prediction.expected_range[0]}–${prediction.expected_range[1]}`:"SELECT MATCH CONTEXT"}</p>{prediction&&<div className="probabilities"><div><b>{Math.round(prediction.probability_30_plus*100)}%</b><span>30+</span></div><div><b>{Math.round(prediction.probability_50_plus*100)}%</b><span>50+</span></div><div><b>{Math.round(prediction.probability_100_plus*100)}%</b><span>100+</span></div></div>}<div className="predict-grid"><label>FORMAT<select value={format} onChange={e=>setFormat(e.target.value as FormatName)}>{Object.keys(archiveData.formats).map(f=><option key={f}>{f}</option>)}</select></label><label>BATTING POSITION<input type="number" min="1" max="11" value={position} onChange={e=>setPosition(Number(e.target.value))}/></label><label>OPPONENT<select value={opponent} onChange={e=>setOpponent(e.target.value)}>{opponents.map(o=><option key={o}>{o}</option>)}</select></label><label>VENUE<select value={venue} onChange={e=>setVenue(e.target.value)}>{venues.map(v=><option key={v}>{v}</option>)}</select></label></div><button onClick={run}>Generate estimate <ArrowUpRight/></button><small>Historical estimates are uncertain. The chronological test R² is {archiveData.modelMetrics.regression[archiveData.modelMetrics.selected_regressor as keyof typeof archiveData.modelMetrics.regression].r2}; use probabilities as model outputs, not forecasts of certainty.</small></div></section> }

type AskResponse = { answer:string; evidence:Array<Record<string,string|number|null>>; status:string };
const suggestedQuestions = ["How has KL Rahul performed against England?","Compare KL Rahul as opener vs No. 5","Which opponent has he scored most runs against?","What are his best IPL seasons?","Show his Test centuries","What is his recent form?","What is his highest ODI score?","Show his dismissal patterns","What is his latest Form Index?"];
function AskKLR(){const [question,setQuestion]=useState("");const [response,setResponse]=useState<AskResponse|null>(null);const [loading,setLoading]=useState(false);async function ask(text=question){if(!text.trim())return;setQuestion(text);setLoading(true);try{const res=await fetch(`${process.env.NEXT_PUBLIC_KLR_API_URL||"http://localhost:8000"}/ask`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({question:text})});if(!res.ok)throw new Error();setResponse(await res.json())}catch{setResponse({answer:"ASK KLR cannot reach the statistics service. Start FastAPI on port 8000 and try again.",evidence:[],status:"error"})}finally{setLoading(false)}}return <section id="ask-klr" className="ask"><div className="ask-heading"><p>07 / Statistics assistant</p><h2>ASK<br/><i>KLR</i></h2><span>Ask about the data—not the person. Every answer is calculated from the supplied Cricsheet innings.</span></div><div className="ask-console"><div className="ask-suggestions">{suggestedQuestions.map(q=><button key={q} onClick={()=>ask(q)}>{q}</button>)}</div><form onSubmit={e=>{e.preventDefault();ask()}}><label htmlFor="ask-question">YOUR QUESTION</label><div><input id="ask-question" value={question} onChange={e=>setQuestion(e.target.value)} placeholder="e.g. Which opponent has he scored most runs against?"/><button disabled={loading||!question.trim()}>{loading?"Searching…":"Ask"}<ArrowUpRight/></button></div></form><div className={`ask-answer ${response?.status||"idle"}`} aria-live="polite">{response?<><span>{response.status.toUpperCase()}</span><p>{response.answer}</p>{response.evidence.length>0&&<div className="evidence-list">{response.evidence.slice(0,10).map((row,i)=><div key={i}>{Object.entries(row).slice(0,5).map(([key,value])=><span key={key}><small>{key.replaceAll("_"," ")}</small><b>{String(value??"—")}</b></span>)}</div>)}</div>}</>:<p>Choose a question or type your own. Unsupported data is identified rather than invented.</p>}</div></div></section>}

function Finale() { return <section className="finale"><div className="then-now"><div><span>THEN</span><Image src="/images/rahul/journey/rahul-early.webp" alt="A young KL Rahul" fill sizes="40vw"/></div><ArrowDownRight/><div><span>NOW</span><Image src="/images/rahul/journey/india-current.jpg" alt="KL Rahul in the current era" fill sizes="40vw"/></div></div><h2>THE GAME CHANGED.<br /><i>SO DID HE.</i></h2><div className="final-screen"><span>KLR01</span><h2>THE<br />STORY<br /><i>CONTINUES.</i></h2></div></section> }

export function ArchiveExperience() {
  const { scrollYProgress } = useScroll(); const scaleX = useSpring(scrollYProgress,{ stiffness:120,damping:28,mass:.3 });
  const [loaded,setLoaded]=useState(false); const reduce=useReducedMotion(); useEffect(()=>{const t=setTimeout(()=>setLoaded(true), reduce?0:1100);return()=>clearTimeout(t)},[reduce]);
  return <><AnimatePresence>{!loaded && <motion.div className="loader" exit={{ y:"-100%" }} transition={{ duration:.7,ease:[.76,0,.24,1] }}><span>KLR01</span><div><motion.i initial={{scaleX:0}} animate={{scaleX:1}} transition={{duration:.8}}/></div><small>THE RAHUL ARCHIVE</small></motion.div>}</AnimatePresence><motion.div className="progress" style={{scaleX}}/><Navigation/><main><MinimalistHero/><Journey/><StatsLab/><CenturyVault/><Records/><Gallery/><Predictor/><AskKLR/><Finale/></main><footer><div><b>KLR01</b><span>THE RAHUL ARCHIVE</span></div><p>An independent fan-made interactive tribute. Statistics derived from the supplied Cricsheet JSON archives. Not affiliated with KL Rahul, BCCI, IPL, or any franchise.</p><a href="#home">BACK TO TOP ↑</a></footer></>;
}
